python3 -c "
import sys, json, re
try:
    data = json.load(sys.stdin)
except:
    sys.exit(0)
path = data.get('tool_input', {}).get('file_path', '') or data.get('file_path', '')

# Validate config/ JSON files
if '/config/' in path and path.endswith('.json'):
    try:
        json.load(open(path))
        print(f'JSON valid: {path}')
    except Exception as e:
        print(f'JSON SYNTAX ERROR in {path}: {e}', file=sys.stderr)
        sys.exit(1)

# Validate _tools/ frontmatter
if '/_tools/' in path and path.endswith('.md'):
    try:
        content = open(path).read()
        required = ['name:', 'url:', 'date_added:', 'peters_pick:', 'create_content:', 'content_created:', 'public:']
        missing = [f for f in required if f not in content]
        if missing:
            print(f'WARNING: _tools/ frontmatter missing required fields: {missing}', file=sys.stderr)
        bool_fields = re.findall(r'(peters_pick|create_content|content_created|public):\s*(.+)', content)
        bad = [(k, v.strip()) for k, v in bool_fields if v.strip() not in ('true', 'false')]
        if bad:
            print(f'WARNING: boolean fields must be true/false, got: {bad}', file=sys.stderr)
    except Exception as e:
        print(f'Could not validate {path}: {e}', file=sys.stderr)

# Check Liquid tag balance in _layouts/ HTML files
if '/_layouts/' in path and path.endswith('.html'):
    try:
        content = open(path).read()
        opens = len(re.findall(r'\{%-?\s*(if|for|unless|case|block|capture|form|paginate|tablerow|render|raw)\b', content))
        closes = len(re.findall(r'\{%-?\s*(endif|endfor|endunless|endcase|endblock|endcapture|endform|endpaginate|endtablerow|endrender|endraw)\b', content))
        if opens != closes:
            print(f'WARNING: Liquid tag imbalance in {path}: {opens} open vs {closes} close tags', file=sys.stderr)
        else:
            print(f'Liquid tags balanced ({opens} pairs): {path}')
    except Exception as e:
        print(f'Could not check Liquid tags in {path}: {e}', file=sys.stderr)
"
